-- Resync identity sequences.
--
-- The explicit ids inserted above do not advance the GENERATED BY DEFAULT
-- AS IDENTITY sequences, so each sequence is pointed at its current maximum
-- to prevent collisions on future inserts.
--
-- An empty table is left at its initial position: setval() refuses a value that
-- is below the sequence's minimum, so the empty case uses the first value with
-- is_called = false instead. That also lets the importer run against an empty
-- legacy dump, which is how the migration is exercised without production data.

DO $$
DECLARE
  t regclass;
  seq_name text;
  max_id bigint;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'public.users',
    'public.offerings',
    'public.allowed_file_types',
    'public.exercises',
    'public.exercises_attached_files',
    'public.exercises_compilation_files',
    'public.exercises_test_cases',
    'public.exercises_test_cases_files',
    'public.commits'
  ]::regclass[]
  LOOP
    seq_name := pg_get_serial_sequence(t::text, 'id');

    EXECUTE format('SELECT COALESCE(max(id), 0) FROM %s', t::text) INTO max_id;

    PERFORM setval(seq_name, GREATEST(max_id, 1), max_id > 0);
  END LOOP;
END;
$$;
